                    }
                }
            }
        }

        // Sleep for delay
        usleep(delay * 100000);
    }

    // Reset terminal mode
    reset_terminal_mode(&oldt);
}

int main(int argc, char *argv[]) {
    parse_args(argc, argv);
    run();
    return 0;
